import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import api from '../../utils/api';

const DIET_OPTIONS = ['No Preference', 'Vegetarian', 'Vegan', 'Non-Vegetarian', 'Jain'];
const COMMON_ALLERGENS = ['Nuts', 'Dairy', 'Gluten', 'Eggs', 'Shellfish', 'Soy'];

export default function MysteryBoxPage() {
  const navigate = useNavigate();
  const [budget, setBudget] = useState('');
  const [diet, setDiet] = useState('No Preference');
  const [allergies, setAllergies] = useState([]);
  const [address, setAddress] = useState('');
  const [loading, setLoading] = useState(false);
  const [reveal, setReveal] = useState(null);

  const toggleAllergen = (a) =>
    setAllergies((prev) => (prev.includes(a) ? prev.filter((x) => x !== a) : [...prev, a]));

  const handleSurpriseMe = async () => {
    if (!budget || isNaN(budget) || Number(budget) < 50) {
      return toast.error('Enter a budget of ₹50 or more');
    }
    if (!address.trim()) {
      return toast.error('Please enter your delivery address');
    }
    setLoading(true);
    try {
      const res = await api.post('/features/mystery', {
        budget: Number(budget),
        diet,
        allergies,
        address,
      });
      setReveal(res.data);
    } catch (e) {
      toast.error(e.response?.data?.message || 'No Mystery Box available right now');
    } finally {
      setLoading(false);
    }
  };

  if (reveal) {
    return (
      <div className="min-h-screen bg-gray-900 text-white flex items-center justify-center p-6">
        <div className="bg-gray-800 rounded-2xl p-8 max-w-md w-full text-center shadow-2xl border border-green-500">
          <div className="text-6xl mb-4">🎲</div>
          <h2 className="text-3xl font-extrabold mb-2">Your Mystery Box!</h2>
          <p className="text-gray-400 mb-4">From: {reveal.restaurant.emoji} {reveal.restaurant.name}</p>
          <div className="text-2xl font-bold text-orange-500 mb-6 drop-shadow-lg">🍽️ {reveal.reveal}</div>
          <p className="text-gray-300 text-sm mb-8">{reveal.message}</p>
          <button
            onClick={() => navigate(`/track/${reveal.order._id}`)}
            className="w-full bg-orange-500 hover:bg-orange-600 text-white font-bold py-3 px-4 rounded-xl transition duration-200 mb-4"
          >
            Track My Order →
          </button>
          <button
            onClick={() => { setReveal(null); setBudget(''); }}
            className="text-orange-500 hover:text-orange-400 text-sm font-semibold"
          >
            Order Another Mystery Box
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 text-white pb-20">
      <div className="bg-gray-800 p-8 text-center border-b border-gray-700">
        <div className="text-6xl mb-4">🎲</div>
        <h1 className="text-3xl font-extrabold text-white">Mystery Box</h1>
        <p className="text-gray-400 mt-3 text-sm max-w-md mx-auto leading-relaxed">
          Can't decide? Let us surprise you! A highly-rated restaurant creates a fresh meal from today's best ingredients — within your budget.
        </p>
      </div>

      <div className="max-w-xl mx-auto px-4 mt-8 space-y-6">
        <div className="space-y-2">
          <label className="block text-sm font-bold text-white">💰 Your Budget (₹)</label>
          <input
            type="number"
            className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-orange-500 transition"
            placeholder="e.g. 200"
            value={budget}
            onChange={(e) => setBudget(e.target.value)}
          />
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-white">🥗 Dietary Preference</label>
          <div className="flex flex-wrap gap-2">
            {DIET_OPTIONS.map((d) => (
              <button
                key={d}
                onClick={() => setDiet(d)}
                className={`px-4 py-2 rounded-full text-sm transition font-medium ${
                  diet === d ? 'bg-orange-500 text-white' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                }`}
              >
                {d}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-white">⚠️ Allergies / Avoid</label>
          <div className="flex flex-wrap gap-2">
            {COMMON_ALLERGENS.map((a) => (
              <button
                key={a}
                onClick={() => toggleAllergen(a)}
                className={`px-4 py-2 rounded-full text-sm transition font-medium ${
                  allergies.includes(a) ? 'bg-red-600 text-white' : 'bg-gray-800 text-gray-400 hover:bg-gray-700'
                }`}
              >
                {allergies.includes(a) ? '✓ ' : ''}{a}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-2">
          <label className="block text-sm font-bold text-white">📍 Delivery Address</label>
          <textarea
            className="w-full bg-gray-800 border border-gray-700 rounded-xl p-4 text-white placeholder-gray-500 focus:outline-none focus:border-orange-500 transition min-h-[100px]"
            placeholder="Enter your delivery address"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
          />
        </div>

        <div className="bg-gray-800/50 border border-green-500/30 rounded-xl p-5 mt-8">
          <h3 className="text-green-500 font-bold mb-3">How It Works</h3>
          <ul className="space-y-2 text-sm text-gray-400">
            <li>🍳 Restaurants use overstocked, ultra-fresh ingredients</li>
            <li>♻️ Helps reduce food waste</li>
            <li>🎉 Your meal is a genuine surprise — embrace the adventure!</li>
          </ul>
        </div>

        <button
          onClick={handleSurpriseMe}
          disabled={loading}
          className={`w-full mt-8 bg-orange-500 hover:bg-orange-600 text-white font-extrabold py-4 rounded-xl text-lg transition shadow-lg ${
            loading ? 'opacity-50 cursor-not-allowed' : 'hover:scale-[1.02]'
          }`}
        >
          {loading ? 'Processing...' : '🎲 Surprise Me!'}
        </button>
      </div>
    </div>
  );
}
